const skillGuides:Record<string,{when:string;steps:string[];shortcut:string;trap:string}>={
base:{when:'题干给出现期量和增长率，问“上年同期”“基期”是多少。',steps:['圈出本期量和增长率，先判断增长还是下降。','增长时：基期=现期÷(1+r)；下降时：基期=现期÷(1−r)。','把除法转成分数乘法，如÷1.2=×5/6，÷1.25=×4/5。','根据选项差距决定是否截位，最后检查结果应小于增长情形的现期量。'],shortcut:'1.1、1.2、1.25、1.5分别对应乘10/11、5/6、4/5、2/3。',trap:'不能用现期量×(1−增长率)求基期；下降时也不能把增长率加1。'},
current:{when:'题干给出基期量和同比增长/下降幅度，问本期量。',steps:['确认给出的是上年数据（基期量）。','增长：现期=基期×(1+r)；下降：现期=基期×(1−r)。','拆分乘法，例如×1.15=原数+原数的10%+5%。','用数量级或选项末位检查结果。'],shortcut:'增长15%就算原数的1.1倍再加5%；增长25%可先÷4求增量。',trap:'不要把增长量当成现期量；下降时是减去增量。'},
increase:{when:'问“增加多少”“增长量”“比上年多多少”，不是问本期总量。',steps:['找到基期量和增长率。','增长量=基期量×增长率；下降量取负或表述为减少量。','把百分数拆分：15%=10%+5%，12.5%=1/8。','检查增长量应小于基期量（常见增长率小于100%）。'],shortcut:'基期量×12.5%=基期量÷8；×20%=÷5；×25%=÷4。',trap:'增长量的基数是基期量，不是现期量。'},
rate:{when:'问同比增长率、增幅、增长速度，给出增长量和基期量。',steps:['先算增长量=现期−基期（若题目已给则直接取）。','增长率=增长量÷基期量。','先约分，看是否接近1/8、1/6、1/5、1/4、1/3。','不能约分时分子分母同步截位，保留前三位有效数字再除。'],shortcut:'常见分数：1/8=12.5%，1/6≈16.7%，1/5=20%，1/4=25%，1/3≈33.3%。',trap:'分母是基期量；不要误用现期量，也不要把增长量÷现期量当增长率。'},
share:{when:'问“占比”“比重”“占总量的比例”，给出部分量和整体量。',steps:['明确部分量是谁、整体量是谁，避免分子分母颠倒。','比重=部分量÷整体量×100%。','先约分，或把分子分母同步截位做直除。','结果通常在0%—100%之间，利用范围排除离谱选项。'],shortcut:'部分量若约为整体的1/4、1/5、1/8，直接对应25%、20%、12.5%。',trap:'比重的分母是整体量，不是部分量；百分数答案记得乘100%。'},
average:{when:'问平均每人、平均每月、单位面积产量、人均收入等。',steps:['找总量和份数（人数、月份、面积等）。','平均数=总量÷份数，先统一单位。','能约分先约分；不能整除时按选项差距截位估算。','若比较两期平均数，分别算总量/份数，不能只比较总量。'],shortcut:'先把总量和份数约分；份数接近整十时可拆成除以10再微调。',trap:'总量增长不代表平均数一定增长；份数变化会改变平均数。'},
multiple:{when:'问“A是B的几倍”“是平均水平的多少倍”。',steps:['确认A是被比较量，B是标准量。','倍数=A÷B；若问“多几倍”，再减去1。','先估数量级，再约分或截位直除。','检查倍数方向：A大于B，A/B应大于1。'],shortcut:'若分母可化成100、1000，先同步缩放；选项差距大时只保留两三位有效数字。',trap:'“是几倍”与“比……多几倍”差1；倍数不是百分数。'},
shareChange:{when:'题目给出部分和整体两期增长率，问比重上升/下降或变化百分点。',steps:['先比较部分增长率a与整体增长率b。','a>b，比重上升；a<b，比重下降；相等则比重不变。','若只问方向，比较增速即可，不必计算两个比重。','若问变化多少个百分点，再算本期部分/整体−基期部分/整体。'],shortcut:'记住“部分增速高于整体增速，比重上升”；先判方向可秒排两个选项。',trap:'比重变化用“百分点”，不是直接说增长了百分之几；方向判断不能反过来。'}
};
