const fmt=(n:number)=>Number.isInteger(n)?String(n):String(Number(n.toFixed(4)));
type AnswerDiagnosis={cause:string;title:string;detail:string;next:string};
function closeTo(a:number,b:number,tolerance=0.025){return Number.isFinite(a)&&Number.isFinite(b)&&Math.abs(a-b)<=Math.max(0.01,Math.abs(b)*tolerance)}
function diagnoseAnswer(q:Q,value:number):AnswerDiagnosis{
 if(q.unit==='%'&&(closeTo(value,q.answer/100)||closeTo(value,q.answer*100)))return {cause:'计算执行错误',title:'可能混淆了百分数与小数',detail:'本题要求用百分数数值作答。比如 12.5% 应输入 12.5，而不是 0.125；先确认输入框要求的单位。',next:'把计算结果统一换成题目要求的单位，再检查小数点位置。'};
 if(q.skill==='shareChange'&&Math.sign(value)!==Math.sign(q.answer)&&Math.abs(value)>0.01)return {cause:'算法选择错误',title:'比重变化方向可能判断反了',detail:'两期比重先比较部分增长率与整体增长率：部分增速更高，比重上升；更低则下降。',next:'先比较两个增速判断正负，再计算变化幅度，单位使用“百分点”。'};
 if(q.answer>0&&closeTo(value,1/q.answer,0.04))return {cause:'算法选择错误',title:'可能把分子和分母颠倒了',detail:'你的结果接近正确答案的倒数。请重新确认题目中的比较量、标准量，或部分量、整体量。',next:'回到题干标记“谁除以谁”，先写出分子和分母，再进行计算。'};
 if(q.answer!==0&&(closeTo(value,q.answer*10)||closeTo(value,q.answer/10)||closeTo(value,q.answer*100)||closeTo(value,q.answer/100)))return {cause:'计算执行错误',title:'结果数量级可能偏了',detail:'你的答案与正确结果相差约 10 倍或 100 倍，常见原因是百分数换算或小数点位置。',next:'先估算结果应处于什么数量级，再检查百分号、单位和小数点。'};
 if(q.answer!==0&&Math.abs(value-q.answer)/Math.abs(q.answer)<=0.04)return {cause:'计算执行错误',title:'思路接近，重点检查精度',detail:'你的结果与标准答案比较接近，可能是截位过早、四舍五入或中间步骤精度损失。',next:'保留更多有效数字到最后一步，再按题目要求统一舍入。'};
 return {cause:'待归因',title:'暂未识别出典型错误模式',detail:'先不要急着记公式。重新核对题目所求、材料数据对象、年份和单位，再逐步检查列式。',next:'按“识别题型 → 定位数据 → 选择公式 → 检查计算”四步回看。'};
}
function explanationSteps(text:string){const parts=text.split(/(?=[①②③④⑤⑥⑦⑧⑨])/).map(x=>x.replace(/^[①②③④⑤⑥⑦⑧⑨]\s*/,'').trim()).filter(Boolean);return parts.length?parts:[text];}

