const roadmapTopicsWithNames=roadmapTopics.map(t=>({...t,name:skills.find(s=>s.id===t.id)?.name||t.id,tip:skills.find(s=>s.id===t.id)?.tip||t.focus}));
const roadmapDays=Array.from({length:30},(_,i)=>({day:i+1,topic:roadmapTopicsWithNames[i<8?i:(i<16?(i-8)%8:(i-16)%8)],kind:i<8?'知识打底':i<16?'专项强化':'综合巩固',extra:i<8?'理解公式、整理关键词并完成5道基础题':i<16?'完成10道针对性练习，记录错因':'完成一组混合题并复盘错题'}));
