type ExamResult={id:string;date:string;score:number;correct:number;total:number;seconds:number;details:{question:Q;answer:number|null;correct:boolean}[]};
type ReviewTask={question:Q;due:string;attempts:number};
function makeDailyPlan(records:Rec[]):DailyPlan{const date=new Date().toLocaleDateString('zh-CN'),todayKey=new Date().toISOString().slice(0,10);let schedule:Record<string,{due:string;interval:number;streak:number;last:string}>={};try{schedule=JSON.parse(localStorage.getItem('xs_review_schedule')||'{}')}catch{}const dueIds=new Set(Object.entries(schedule).filter(([,v])=>v.due<=todayKey).map(([id])=>id));const dueQs=records.filter(r=>dueIds.has(r.question.id)).map(r=>r.question).filter((q,i,a)=>a.findIndex(x=>x.id===q.id)===i).slice(0,3);const performance=skills.map(s=>{const xs=records.filter(r=>r.question.skill===s.id).slice(0,8);return {id:s.id,count:xs.length,rate:xs.length?xs.filter(r=>r.correct).length/xs.length:1,avg:xs.length?xs.reduce((n,r)=>n+r.seconds,0)/xs.length:0}}).filter(x=>x.count>0).sort((a,b)=>a.rate-b.rate||b.avg-a.avg);const weak=performance[0]?.id||'base';const weakQs=Array.from({length:3},()=>generateQuestion(weak)),mixedQs=Array.from({length:3},()=>generateQuestion('all')),dayIndex=new Date().getDate()%materialSets.length,materialQs=materialSets[dayIndex].questions.slice(0,3).map(q=>({...q,id:'daily-'+date+'-'+q.id}));const questions=[...dueQs,...weakQs,...mixedQs,...materialQs];return {date,questions,done:[]};}
