useEffect(()=>{if(!examMode||!examStarted||examReport)return;const tick=()=>{const left=Math.max(0,examMinutes*60-Math.floor((Date.now()-examStarted)/1000));setExamRemaining(left);if(left===0)finishExam();};tick();const id=window.setInterval(tick,1000);return()=>clearInterval(id)},[examMode,examStarted,examReport,examAnswers,examQuestions,examIndex,active,input,examMinutes]);
