function generateLessonRetry(course:string){
 const pick=(min:number,max:number)=>Math.floor(Math.random()*(max-min+1))+min;
 if(course==='base'){
  const down=Math.random()<.5,rate=pick(10,35),factor=down?1-rate/100:1+rate/100;
  const correct=factor.toFixed(2),wrong1=(down?1+rate/100:1-rate/100).toFixed(2),wrong2=(rate/100).toFixed(2);
  const options=[correct,wrong1,wrong2].sort(()=>Math.random()-.5),answer=options.indexOf(correct);
  return {check:`某指标同比${down?'下降':'增长'}${rate}% ，现期量与基期量之间应使用哪个倍数？`,options,answer,why:`${down?'下降':'增长'}${rate}%意味着现期量是基期量的${correct}倍，因此现期量=基期量×${correct}。`};
 }
 if(course==='growth'){
  const base=pick(120,900),rate=pick(5,30),inc=Math.round(base*rate/100),current=base+inc;
  const options=[String(inc),String(current),String(Math.round(inc/current*100))+'%'].sort(()=>Math.random()-.5),answer=options.indexOf(String(inc));
  return {check:`某指标由${base}增长到${current}，增长量是多少？`,options,answer,why:`增长量=现期量−基期量=${current}−${base}=${inc}。`};
 }
 if(course==='share'){
  const total=pick(300,2000),part=pick(2,6)*10,portion=Math.round(total*part/100),rate=portion/total*100,correct=rate.toFixed(1)+'%';
  const options=[correct,(rate+7).toFixed(1)+'%',(100-rate).toFixed(1)+'%'].sort(()=>Math.random()-.5),answer=options.indexOf(correct);
  return {check:`某地总量为${total}，其中某部分为${portion}，该部分占整体的比重约为多少？`,options,answer,why:`比重=部分量÷整体量=${portion}÷${total}≈${correct}。`};
 }
 if(course==='average'){
  const people=pick(8,30),avg=pick(3,18),total=people*avg;
  const options=[String(avg),String(total),String(people)].sort(()=>Math.random()-.5),answer=options.indexOf(String(avg));
  return {check:`某单位${people}名员工的总收入为${total}万元，人均收入是多少？`,options,answer,why:`平均数=总量÷份数=${total}÷${people}=${avg}万元/人。`};
 }
 if(course==='multiple'){
  const standard=pick(40,200),times=pick(12,30)/10,compare=Math.round(standard*times),correct=times.toFixed(1)+'倍';
  const options=[correct,(times+0.5).toFixed(1)+'倍',(times-0.3).toFixed(1)+'倍'].sort(()=>Math.random()-.5),answer=options.indexOf(correct);
  return {check:`甲指标为${compare}，乙指标为${standard}，甲是乙的多少倍？`,options,answer,why:`倍数=比较量÷标准量=${compare}÷${standard}=${correct}。`};
 }
 const partRate=pick(5,25),totalRate=pick(5,25),correct=partRate>totalRate?'上升':partRate<totalRate?'下降':'不变';
 const options=['上升','下降','不变'].sort(()=>Math.random()-.5),answer=options.indexOf(correct);
 return {check:`某地区部分量同比增长${partRate}%，整体量同比增长${totalRate}%，部分占整体的比重如何变化？`,options,answer,why:`部分增速${partRate>totalRate?'高于':partRate<totalRate?'低于':'等于'}整体增速，因此比重${correct}。`};
}
function begin(q:Q){setActive(q);setInput('');setResult(null);setElapsed(0);setStarted(Date.now());setPage('practice')}
function startCoachPractice(skillId:string){const qs=Array.from({length:6},()=>generateQuestion(skillId));setExtraQuestions(old=>[...old,...qs]);setFilter(skillId);setReviewMode(false);setPlanMode(false);setSessionMaterialId(null);begin(qs[0]);}
function startAdaptiveLesson(cause=adaptiveCause){
 const target=adaptiveCauseTips[cause]||adaptiveCauseTips['题型识别错误'];
 if(target.target==='ability'||target.target==='locate'||target.target==='algorithm'){
   setAbilityTab(target.target==='ability'?'identify':target.target);setAbilityIndex(0);setAbilityChoice(null);setAbilityStarted(Date.now());nav('ability');return;
 }
 const weakSkill=[...skillPerformance].filter(x=>x.count>0).sort((a,b)=>a.rate-b.rate||b.avg-a.avg)[0]?.id||'base';
 startCoachPractice(weakSkill);
}


function startReview(cause='全部原因'){const today=new Date().toISOString().slice(0,10);const dueIds=Object.entries(reviewSchedule).filter(([,v])=>v.due<=today).map(([id])=>id);const qs=wrong.map(r=>r.question).filter((q,i,a)=>a.findIndex(x=>x.id===q.id)===i).filter(q=>(cause==='全部原因'||cause==='到期复习'||(wrongCauses[q.id]||'待归因')===cause)&&(cause!=='到期复习'||dueIds.includes(q.id)));setReviewQueue(qs);setReviewIndex(0);setReviewMode(true);if(qs[0])begin(qs[0]);}
function startExam(){
 const matchesDifficulty=(q:Q)=>examDifficulty==='全部难度'||(examDifficulty==='基础'?/基础|简单/.test(q.level):examDifficulty==='进阶'?/中等|进阶/.test(q.level):/困难|较难|挑战/.test(q.level));
 const skillId=examSkill==='全部题型'?'all':(skills.find(s=>s.name===examSkill)?.id||examSkill);
 const eligibleMaterials=materialSets.map(m=>({...m,questions:m.questions.map((q,index)=>({...q,materialId:m.id,materialQuestionIndex:index})) .filter(q=>matchesDifficulty(q)&&(skillId==='all'||q.skill===skillId))})).filter(m=>m.questions.length>=3).sort(()=>Math.random()-.5);
 const materialBlockCount=skillId==='all'?Math.min(eligibleMaterials.length,Math.max(1,Math.floor(examCount/10))):0;
 const qs:Q[]=[];
 for(const material of eligibleMaterials.slice(0,materialBlockCount)){
   const block=material.questions.slice(0,Math.min(5,examCount-qs.length));
   qs.push(...block);
 }
 const materialIds=new Set(materialSets.flatMap(m=>m.questions.map(q=>q.id)));
 let pool=allQuestions.filter(q=>matchesDifficulty(q)&&(skillId==='all'||q.skill===skillId)&&!materialIds.has(q.id));
 if(skillId!=='all'&&pool.length<examCount){
   pool=allQuestions.filter(q=>matchesDifficulty(q)&&q.skill===skillId);
 }
 const shuffled=[...pool].sort(()=>Math.random()-.5);
 qs.push(...shuffled.slice(0,Math.max(0,examCount-qs.length)));
 if(qs.length<examCount){
   const fallback=allQuestions.filter(q=>!qs.some(x=>x.id===q.id)).sort(()=>Math.random()-.5);
   qs.push(...fallback.slice(0,examCount-qs.length));
 }
 setExamQuestions(qs);setExamAnswers(Array(qs.length).fill(null));setExamIndex(0);setExamReport(null);setExamRemaining(examMinutes*60);setExamStarted(Date.now());setExamMode(true);setPlanMode(false);begin(qs[0]);}
function finishExam(){if(!examMode||examReport)return;const answers=examAnswers.map((a,i)=>i===examIndex&&active&&input.trim()?Number(input):a);const details=examQuestions.map((q,i)=>({question:q,answer:answers[i],correct:answers[i]!==null&&Math.abs((answers[i] as number)-q.answer)<=(Number.isInteger(q.answer)?0:.006)}));const correct=details.filter(x=>x.correct).length;const report:ExamResult={id:crypto.randomUUID(),date:new Date().toLocaleString('zh-CN'),score:Math.round(correct/Math.max(1,details.length)*100),correct,total:details.length,seconds:Math.min(examMinutes*60,Math.floor((Date.now()-examStarted)/1000)),details};setExamHistory(old=>[report,...old]);setExamReport(report);setExamMode(false);setActive(null);setStarted(0);setPage('exam');}
function jumpExam(index:number){if(index<0||index>=examQuestions.length)return;const updated=examAnswers.map((x,i)=>i===examIndex?(input.trim()?Number(input):null):x);setExamAnswers(updated);setExamIndex(index);setInput(updated[index]===null?'':String(updated[index]));setResult(null);setActive(examQuestions[index]);setElapsed(0);setStarted(Date.now());}
function examNext(){if(!active)return;const v=input.trim()?Number(input):null;setExamAnswers(old=>old.map((x,i)=>i===examIndex?v:x));setResult(null);setInput('');setStarted(0);if(examIndex===examQuestions.length-1){const updated=examAnswers.map((x,i)=>i===examIndex?v:x);const details=examQuestions.map((q,i)=>({question:q,answer:updated[i],correct:updated[i]!==null&&Math.abs((updated[i] as number)-q.answer)<=(Number.isInteger(q.answer)?0:.006)}));const correct=details.filter(x=>x.correct).length;const report:ExamResult={id:crypto.randomUUID(),date:new Date().toLocaleString('zh-CN'),score:Math.round(correct/details.length*100),correct,total:details.length,seconds:Math.min(examMinutes*60,Math.floor((Date.now()-examStarted)/1000)),details};setExamHistory(old=>[report,...old]);setExamReport(report);setExamMode(false);setActive(null);setPage('exam');return;}const ni=examIndex+1;setExamIndex(ni);begin(examQuestions[ni]);}
function beginMaterial(id:string){const m=materialSets.find(x=>x.id===id);if(!m)return;setSessionMaterialId(id);setSessionIndex(0);begin(m.questions[0]);}
function exitMaterial(){setSessionMaterialId(null);setSessionIndex(0);setActive(null);setResult(null);setStarted(0);setPage('materials');}
const sessionMaterial=materialSets.find(m=>m.id===sessionMaterialId);const activeExamMaterial=examMode&&active?.materialId?materialSets.find(m=>m.id===active.materialId):undefined;const visibleMaterial=sessionMaterial||activeExamMaterial;
function submit(){if(!active||result||!input.trim())return;const value=Number(input);if(!Number.isFinite(value))return;const ok=Math.abs(value-active.answer)<=(Number.isInteger(active.answer)?0:.006);if(!examMode)setRecords(old=>[{id:crypto.randomUUID(),answer:value,correct:ok,seconds:elapsed,date:new Date().toLocaleDateString('zh-CN'),question:active},...old]);if(!examMode){const today=new Date();const iso=(d:Date)=>d.toISOString().slice(0,10);if(!ok){const due=new Date(today);due.setDate(due.getDate()+1);setReviewSchedule(old=>({...old,[active.id]:{due:iso(due),interval:1,streak:0,last:iso(today)}}));}else if(reviewMode&&reviewSchedule[active.id]){const previous=reviewSchedule[active.id];const nextStreak=previous.streak+1;const interval=nextStreak===1?3:nextStreak===2?7:14;const due=new Date(today);due.setDate(due.getDate()+interval);setReviewSchedule(old=>({...old,[active.id]:{due:iso(due),interval,streak:nextStreak,last:iso(today)}}));}}if(reviewMode&&ok)setReviewedIds(old=>old.includes(active.id)?old:[...old,active.id]);if(dailyPlan.questions.some(q=>q.id===active.id))setDailyPlan(p=>({...p,done:p.done.includes(active.id)?p.done:[...p.done,active.id]}));setResult({ok,value});setStarted(0)}
function next(){if(reviewMode){const ni=reviewIndex+1;if(ni<reviewQueue.length){setReviewIndex(ni);begin(reviewQueue[ni]);}else{setReviewMode(false);setActive(null);setResult(null);setPage('wrong');}return;}if(planMode){const nextQ=dailyPlan.questions.find(q=>!dailyPlan.done.includes(q.id));if(nextQ){begin(nextQ);}else{setPlanMode(false);setPage('plan');setActive(null);setStarted(0);}return;}if(sessionMaterial){const nextIndex=sessionIndex+1;if(nextIndex<sessionMaterial.questions.length){setSessionIndex(nextIndex);begin(sessionMaterial.questions[nextIndex]);}else{setSessionMaterialId(null);setSessionIndex(0);setActive(null);setResult(null);setStarted(0);setPage('materials');setSelectedMaterial(sessionMaterial.id);}return;}const pool=selected.length?selected:allQuestions;const i=pool.findIndex(q=>q.id===active?.id);begin(pool[(i+1)%pool.length])}
