function importData(e:React.ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(String(reader.result));if(Array.isArray(data.records))setRecords(data.records);if(Array.isArray(data.abilityAttempts))setAbilityAttempts(data.abilityAttempts);if(Array.isArray(data.materialDrillAttempts))setMaterialDrillAttempts(data.materialDrillAttempts);if(Array.isArray(data.examHistory))setExamHistory(data.examHistory);if(Array.isArray(data.reviewedIds))setReviewedIds(data.reviewedIds);if(Array.isArray(data.roadmapDone))setRoadmapDone(data.roadmapDone);if(Array.isArray(data.completedCourses))setCompletedCourses(data.completedCourses);if(data.wrongCauses&&typeof data.wrongCauses==='object')setWrongCauses(data.wrongCauses);if(data.reviewSchedule&&typeof data.reviewSchedule==='object')setReviewSchedule(data.reviewSchedule);alert('导入成功，已恢复备份中包含的训练数据')}catch{alert('文件格式不正确')}finally{e.target.value=''}};reader.readAsText(file)}
